def fnote_git(no, h_tr, h_en, maddeler, hedefler):
    """maddeler: [(tr, en)], hedefler: her madde icin hedef -> bulgu karti; her maddenin sonunda ilgili alt basliga ok."""
    from ortak import _kc, git as _git
    ac = ACIK.get(no)
    return ('<article class="fnote"><span class="fc">%s</span><h3>%s</h3>%s<ul>%s</ul></article>'
            % (x("Bulgu %02d" % no, "Finding %02d" % no), x(h_tr, h_en), ('<p class="fac">%s</p>' % x(*ac)) if ac else "", "".join('<li><span class="mtx">%s</span>%s</li>' % (x(*_kc(a, b)), _git(h)) for (a, b), h in zip(maddeler, hedefler))))
    
